          if (row.rider_id) await sql2`update riders set active_order_id = null, status = ${"ONLINE"} where id = ${row.rider_id} and active_order_id = ${row.id}`;
          await sql2`update riders set active_order_id = ${row.id}, status = ${"BUSY"} where id = ${data.riderId}`;
