    mutateSettlement_createServerFn_handler = createServerRpc({
      id: "1ecd7474726af8e978fd5570774a5321db320b4478416d14d8d35b73885b8337",
      name: "mutateSettlement",
      filename: "src/lib/orderking/server/api.ts"
    }, (opts) => mutateSettlement.__executeServer(opts));
    mutateSettlement = createServerFn({ method: "POST" }).middleware([authMiddleware]).validator((input) => input).handler(mutateSettlement_createServerFn_handler, async ({ context: context2, data }) => {
      try {
        const { sql: sql2, actor } = await requireEmployee(context2.userId, "manage_settlements");
        if (!data.reason?.trim()) return {
          ok: false,
          error: "A reason is required.",
          code: "REASON"
        };
        const row = (await sql2`select id, status, version from settlements where org_id = ${actor.orgId} and id = ${data.id}`)[0];
        if (!row) return {
          ok: false,
          error: "Settlement not found.",
          code: "NOT_FOUND"
        };
        if (row.version !== data.version) return {
          ok: false,
          error: "Another employee changed this record. Refresh before continuing.",
          code: "CONFLICT"
        };
        const next = data.action === "flag" ? "FLAGGED" : "APPROVED";
        await sql2`update settlements set status = ${next}, flagged_reason = ${data.reason}, version = ${row.version + 1} where id = ${row.id} and version = ${row.version}`;
        await writeAudit(sql2, actor, {
          action: "SETTLEMENT_" + data.action.toUpperCase(),
          targetType: "settlement",
          targetId: row.id,
          previousState: { status: row.status },
          newState: { status: next },
          reason: data.reason
        });
        return {
          ok: true,
          data: { id: row.id }
        };
      } catch (err2) {
        return fail(err2);
      }
    });
